using System.Security.Claims;using DBM.POS.Domain.Entities;using DBM.POS.Infrastructure.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace DBM.POS.API.Controllers;
[ApiController,Authorize,Route("api/inventory/batches")]
public class BatchController:ControllerBase{private readonly POSDbContext _db;public BatchController(POSDbContext db)=>_db=db;private Guid C=>Guid.Parse(User.FindFirstValue("companyId")!);
[HttpGet]public async Task<IActionResult>Get([FromQuery]Guid?warehouseId,[FromQuery]Guid?productId,[FromQuery]bool activeOnly=true){var q=_db.ProductBatches.AsNoTracking().Where(x=>x.CompanyId==C);if(warehouseId.HasValue)q=q.Where(x=>x.WarehouseId==warehouseId);if(productId.HasValue)q=q.Where(x=>x.ProductId==productId);if(activeOnly)q=q.Where(x=>x.IsActive);return Ok(await q.OrderBy(x=>x.ExpiryDate).ToListAsync());}
[HttpPost]public async Task<IActionResult>Create(RequestDto r){if(!await _db.Products.AnyAsync(x=>x.Id==r.ProductId&&x.CompanyId==C))return BadRequest(new{message="Invalid product."});if(!await _db.Warehouses.AnyAsync(x=>x.Id==r.WarehouseId&&x.CompanyId==C))return BadRequest(new{message="Invalid warehouse."});var b=new ProductBatch{CompanyId=C,ProductId=r.ProductId,VariantId=r.VariantId,WarehouseId=r.WarehouseId,BatchNo=r.BatchNo,ManufactureDate=r.ManufactureDate,ExpiryDate=r.ExpiryDate,CostPrice=r.CostPrice,MRP=r.MRP,Quantity=r.Quantity};_db.ProductBatches.Add(b);await _db.SaveChangesAsync();return Ok(b);}
[HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,RequestDto r){var b=await _db.ProductBatches.FirstOrDefaultAsync(x=>x.CompanyId==C&&x.Id==id);if(b==null)return NotFound();b.BatchNo=r.BatchNo;b.ManufactureDate=r.ManufactureDate;b.ExpiryDate=r.ExpiryDate;b.CostPrice=r.CostPrice;b.MRP=r.MRP;b.Quantity=r.Quantity;b.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();return Ok(b);}
public record RequestDto(Guid ProductId,Guid WarehouseId,string BatchNo,Guid? VariantId=null,DateTime? ManufactureDate=null,DateTime? ExpiryDate=null,decimal CostPrice=0,decimal MRP=0,decimal Quantity=0);}
